import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import PredictionCard, { PersonLink } from './PredictionCard';
import { PageStructure, IndexSidebar } from './PredictionsPage';
import { optionLabel, t, tx } from '../api';
import { call, lookup, num } from '../data';

/** /predictions/:id: one prediction, and who picked what once picks are out in the open. */

export default class PredictionPage extends Page {
  prediction = null;
  missing = false;
  picks = null;
  picksFor = '';
  oninit(vnode) {
    super.oninit(vnode);
    this.bodyClass = 'App--predictions';
    const id = parseInt(m.route.param('id'), 10);
    lookup(id).then(p => {
      this.prediction = p;
      this.missing = !p;
      if (p) {
        app.setTitle(p.title);
        app.history.push('prediction', p.title);
      }
      m.redraw();
    });
  }
  onbeforeupdate() {
    // Load (or reload) who picked what when picks become visible or a pick changes the count.
    const p = this.prediction;
    const key = p ? `${p.id}:${p.picksVisible}:${p.picksCount}:${p.status}:${p.scored}` : '';
    if (p && p.picksVisible && key !== this.picksFor) {
      this.picksFor = key;
      call('GET', `/predictions/${p.id}/picks`).then(res => {
        this.picks = res.data;
        m.redraw();
      });
    }
  }
  view() {
    const p = this.prediction;
    return m(PageStructure, {
      className: "PredictionPage",
      sidebar: () => m(IndexSidebar, null)
    }, m(Link, {
      className: "PredictionPage-back",
      href: app.route('predictions')
    }, m(Icon, {
      name: "fas fa-arrow-left"
    }), " ", t('page.all')), this.missing ? m("p", {
      className: "PredictionsPage-empty"
    }, t('page.missing')) : !p ? m(LoadingIndicator, null) : [m(PredictionCard, {
      prediction: p,
      context: "single",
      ondelete: () => m.route.set(app.route('predictions'))
    }), this.whoPicked(p)]);
  }
  whoPicked(p) {
    if (!p.picksVisible) return m("p", {
      className: "PredictionPage-hidden"
    }, t('single.hidden'));
    if (!this.picks) return null;
    if (!this.picks.length) return m("p", {
      className: "PredictionPage-hidden"
    }, t('single.none'));
    if (p.type === 'number') {
      const unit = p.unit ? ` ${p.unit}` : '';
      return m("section", {
        className: "PredictionWho"
      }, m("h3", null, t('single.who')), m("ol", {
        className: "PredictionWho-list"
      }, this.picks.map(row => m("li", {
        className: row.hit ? 'is-hit' : ''
      }, m(PersonLink, {
        person: row.user
      }), m("span", {
        className: "PredictionWho-value"
      }, num(row.value) + unit), row.points ? m("span", {
        className: "PredictionPoints"
      }, "+", row.points) : null))));
    }
    return m("section", {
      className: "PredictionWho"
    }, m("h3", null, t('single.who')), p.options.map((option, i) => {
      const rows = this.picks.filter(r => r.optionId === option.id);
      return m("div", {
        className: 'PredictionWho-group' + (option.isCorrect ? ' is-correct' : '')
      }, m("h4", null, option.isCorrect && m(Icon, {
        name: "fas fa-circle-check"
      }), " ", optionLabel(p, option, i), ' ', m("span", {
        className: "PredictionWho-count"
      }, tx('card.picks_short', {
        count: rows.length
      }))), rows.length ? m("ul", {
        className: "PredictionWho-people"
      }, rows.map(row => m("li", null, m(PersonLink, {
        person: row.user
      }), row.points ? m("span", {
        className: "PredictionPoints"
      }, "+", row.points) : null))) : m("p", {
        className: "PredictionWho-nobody"
      }, t('single.nobody')));
    }));
  }
}
flarum.reg.add('ernestdefoe-predictions', 'forum/components/PredictionPage', PredictionPage);